import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
});

describe('ChatOrchestrator onError non-Error rejections', () => {
  async function performTest(rejection: unknown) {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      {
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          if (false) yield {} as MessageChunk;
          throw rejection;
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      } as AIProvider,
      promptBuilder,
      undefined,
      {hooks}
    );

    let thrown: unknown;
    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      thrown = e;
    }

    return {thrown, receivedError};
  }

  it('calls onError with coerced Error when provider rejects with a string (HALEngine#95)', async () => {
    const {thrown, receivedError} = await performTest('string boom');

    expect({
      thrown,
      errorIsError: receivedError instanceof Error,
      errorMessage: receivedError?.message,
      // @ts-expect-error cause is not in Error type yet
      errorCause: receivedError?.cause,
    }).toEqual({
      thrown: 'string boom',
      errorIsError: true,
      errorMessage: 'string boom',
      errorCause: 'string boom',
    });
  });

  it('calls onError with coerced Error when provider rejects with a plain object (HALEngine#95)', async () => {
    const reason = {code: 503, detail: 'upstream down'};
    const {thrown, receivedError} = await performTest(reason);

    expect({
      thrown,
      errorIsError: receivedError instanceof Error,
      errorMessage: receivedError?.message,
      // @ts-expect-error cause is not in Error type yet
      errorCause: receivedError?.cause,
    }).toEqual({
      thrown: reason,
      errorIsError: true,
      errorMessage: '[object Object]',
      errorCause: reason,
    });
  });
});

